# Operation R: heist workbook content. Every code block runs through real R to record its output.
CASE_FILES = '''crew <- data.frame(
  codename = c("Ghost", "Viper", "Tinker", "Nova", "Blaze", "Echo"),
  skill    = c("hacker", "driver", "safecracker", "inside man", "explosives", "lookout"),
  city     = c("Berlin", "Tokyo", "Rio", "Berlin", "Tokyo", "Denver"),
  age      = c(29, 34, 51, 26, 40, 23),
  cut_pct  = c(20, 15, 25, 15, 15, 10))
jobs <- data.frame(
  alias  = c("Ghost", "Viper", "Tinker", "Tinker", "Nova", "Rook"),
  target = c("Museum", "Casino", "Bank", "Train", "Casino", "Yacht"),
  payout = c(4.0, 2.5, 6.0, 3.5, 1.8, 5.2),
  year   = c(2025, 2025, 2025, 2026, 2026, 2026))
set.seed(1337)
vault_log <- data.frame(
  night  = 1:60,
  casino = rep(c("Golden Lion", "Silver Palm", "Jade Dragon"), each = 20),
  guards = sample(3:12, 60, replace = TRUE),
  cash_k = round(rnorm(60, mean = 800, sd = 150)),
  alarm  = sample(c(TRUE, FALSE), 60, replace = TRUE, prob = c(0.3, 0.7)),
  shift  = sample(c("day", "night"), 60, replace = TRUE))'''
DPLYR = 'suppressPackageStartupMessages({library(dplyr); library(tidyr)})\n'

M = []

# ------------------------------------------------------------------ 1
M.append(dict(id="m1", num=1, lec="R basics", room="Safehouse", title="The Safehouse",
 tagline="Set up the hideout: RStudio, R Markdown, operators, and the five kinds of values R knows.",
 brief="Every job starts in the safehouse. Before we touch a single vault, we learn the tools: where code goes, how R does math, and what kinds of things R can hold.",
 objectives=["Know the four RStudio panes and the R Markdown basics", "Assign values and use every arithmetic operator, including %% and %/%", "Tell numeric, integer, character and logical apart with class(), is.x() and as.x()", "Handle NA, NULL and NaN without getting burned", "Build conditions with == != < > & | !"],
 setup=CASE_FILES,
 blocks=[
  {"h":"Why R?"},
  {"p":"R was built by statisticians for data. Python is stronger at machine learning but needs <code>pandas</code> to feel like R. SAS is expensive and rigid, even though the FDA requires it. For analyzing data and showing results beautifully, R is the crew's tool of choice."},
  {"h":"The hideout layout: RStudio"},
  {"p":"RStudio is an IDE, an Integrated Development Environment. Tap each pane. Panes can be rearranged in settings, so your layout may differ from this default."},
  {"lab":"rstudio"},
  {"h":"R Markdown: the mission report"},
  {"p":"An <code>.Rmd</code> file mixes writing, code, output, plots and formulas. Press <b>Knit</b> to export HTML, PDF or Word. It's the best way to write homework, and it keeps every output next to the code that made it."},
  {"table":[["Want to…","Do this"],["Heading","Start the line with <code>#</code>, <code>##</code>, <code>###</code>"],["Bullet","Start the line with <code>- </code>"],["Line break","End the line with two spaces"],["New code chunk","<kbd>Ctrl</kbd>+<kbd>Alt</kbd>+<kbd>I</kbd> (Mac: <kbd>Cmd</kbd>+<kbd>Option</kbd>+<kbd>I</kbd>)"],["Run a line","<kbd>Ctrl</kbd>+<kbd>Enter</kbd>"],["Run the chunk","<kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Enter</kbd>"],["Math","LaTeX inside <code>$…$</code> or <code>$$…$$</code>"],["Install the package","<code>install.packages(\"rmarkdown\")</code>"]]},
  {"p":"Math is written in LaTeX. This is the Central Limit Theorem, which you'll watch happen with real physics in Mission 10:"},
  {"math":"\\frac{\\sqrt{n}\\,(\\bar{X}-\\mu)}{\\hat{\\sigma}} \\xrightarrow{d} \\mathcal{N}(0,1)"},
  {"code":"m1_hist","src":"x = rnorm(100)\nhist(x)","plot":True,"seed":1},
  {"h":"Assignment: stashing values"},
  {"p":"<code>=</code> and <code>&lt;-</code> both store a value under a name. The shortcut for <code>&lt;-</code> is <kbd>Alt</kbd>+<kbd>-</kbd>. Names are case sensitive, so <code>loot</code> and <code>Loot</code> are two different variables."},
  {"code":"m1_assign","src":"loot = 250        # thousands of dollars\nloot <- 250\nLoot = 999        # a DIFFERENT variable\nloot\nLoot"},
  {"trap":"Spaces matter. <code>loot &lt; -250</code> asks “is loot less than minus 250?” It does not assign anything."},
  {"h":"Operators: splitting the take"},
  {"code":"m1_ops","src":"loot = 250\ncrew_size = 6\nloot + 50\nloot - 40\nloot * 2\nloot / crew_size\ncrew_size ^ 2\nloot %/% crew_size   # whole thousands each person gets\nloot %% crew_size    # thousands left over after the even split"},
  {"p":"<code>%/%</code> is integer division and <code>%%</code> is the remainder. Together they answer “how many each, and how many left over”: 250 = 6 × 41 + 4."},
  {"h":"Data types"},
  {"p":"The types you'll meet are <b>numeric</b> (double), <b>integer</b>, <b>character</b>, <b>logical</b>, and rarely <b>complex</b>. Three function families let you inspect and convert:"},
  {"ul":["<code>class(x)</code> names the type.","<code>is.xxx(x)</code> asks a yes/no question, such as <code>is.numeric(x)</code>.","<code>as.xxx(x)</code> tries to convert, such as <code>as.integer(x)</code>."]},
  {"code":"m1_types","src":"bags = 3\nclass(bags)\nis.integer(bags)\nbags_int = as.integer(bags)\nclass(bags_int)\nis.numeric(bags_int)     # integers are numeric too\nclass(\"Ghost\")\nclass(TRUE)\nclass(3 + 2i)"},
  {"lab":"typescanner"},
  {"h":"Characters: the code words"},
  {"code":"m1_char","src":"code_word = \"Nightingale\"\nprint(code_word)\nis.character(code_word)\nsafe_code = \"7319\"\nis.numeric(safe_code)\nas.numeric(safe_code) + 1\nas.numeric(code_word)"},
  {"code":"m1_charerr","src":"safe_code + 1"},
  {"h":"NA, NULL, NaN: the unknowns"},
  {"ul":["<code>NA</code> means “not available”: a missing value that still takes up a slot.","<code>NULL</code> means “nothing”: no object at all, length 0.","<code>NaN</code> means “not a number”, like <code>0/0</code>. <code>Inf</code> is what <code>1/0</code> gives."]},
  {"code":"m1_na","src":"guards_on_duty = c(4, NA, 6)   # one shift unknown\nsum(guards_on_duty)\nsum(guards_on_duty, na.rm = TRUE)\nlength(NA)\nlength(NULL)\n0 / 0\n1 / 0\nis.na(NaN)"},
  {"h":"Logic: the laser grid"},
  {"p":"Comparisons (<code>== != &lt; &gt; &lt;= &gt;=</code>) give <code>TRUE</code> or <code>FALSE</code>. Combine them with <code>&amp;</code> (and), <code>|</code> (or) and <code>!</code> (not). Play with the grid until you can predict the door."},
  {"lab":"lasers"},
  {"code":"m1_logic","src":"guards = 3\ncameras_on = TRUE\nalarm_armed = FALSE\nguards < 4\ncameras_on & alarm_armed\ncameras_on | alarm_armed\n!alarm_armed\ngo = (guards < 4) & !alarm_armed\ngo"},
  {"trap":"<code>T</code> and <code>F</code> are shortcuts for TRUE and FALSE, but they're ordinary variables. Anyone can overwrite them, and then your code silently breaks."},
  {"code":"m1_T","src":"T = 0\nT\nisTRUE(T)\nrm(T)     # delete your T and the built-in shortcut comes back\nT"},
 ],
 jobs=[
  {"title":"Split the take","pay":0.5,"prompt":"The crew stole <b>1000</b> (thousand). Six people split it evenly in whole thousands. Store how much <b>each person</b> gets in <code>ans</code>.","starter":"total = 1000\nans = ___","solution":"total = 1000\nans = total %/% 6","hint":"Integer division is <code>%/%</code>."},
  {"title":"Leftovers for the getaway car","pay":0.5,"prompt":"Using the same 1000 and 6 people, store the thousands <b>left over</b> after the even split in <code>ans</code>.","starter":"total = 1000\nans = ___","solution":"total = 1000\nans = total %% 6","hint":"The remainder operator is <code>%%</code>."},
  {"title":"Is the coast clear?","pay":0.8,"prompt":"The variables <code>guards</code>, <code>cameras_on</code> and <code>alarm_armed</code> are set for you. Store <code>TRUE</code> in <code>ans</code> only if there are <b>fewer than 3 guards AND the cameras are off</b>.","setup":"guards = 2\ncameras_on = FALSE\nalarm_armed = TRUE","starter":"ans = ___","solution":"ans = guards < 3 & !cameras_on","hint":"Two conditions joined by <code>&amp;</code>. “Cameras off” is <code>!cameras_on</code>."},
  {"title":"Decode the safe","pay":0.7,"prompt":"The safe code arrived as text: <code>\"750\"</code>. Convert it to a number, add 250, and store the result in <code>ans</code>.","starter":"code_txt = \"750\"\nans = ___","solution":"code_txt = \"750\"\nans = as.numeric(code_txt) + 250","hint":"<code>as.numeric()</code> first, then add."},
 ],
 quiz=[
  {"q":"What does this print?","code":"17 %% 5","choices":["[1] 3.4","[1] 3","[1] 0.4"],"why":"<code>%%</code> is the remainder: 17 = 5 × 3 + <b>2</b>."},
  {"q":"What does this print?","code":"as.integer(3.9)","choices":["[1] 4","[1] 3.9","Error"],"why":"<code>as.integer</code> chops off the decimals. It doesn't round."},
  {"q":"What does this print?","code":"x = 5\nX = 10\nx + 1","choices":["[1] 11","[1] 16","Error: object 'x' not found"],"why":"R is case sensitive, so <code>x</code> is still 5."},
  {"q":"What does this print?","code":"(3 > 2) & (2 > 3)","choices":["[1] TRUE","[1] NA","[1] 1"],"why":"<code>&amp;</code> needs both sides TRUE, and the second one is FALSE."},
  {"q":"Which one has length 0?","choices":["NA","NaN","0"],"answer":"NULL","why":"<code>NULL</code> is the absence of an object. The others each occupy one slot."},
  {"q":"What does this print?","code":"sum(c(4, NA, 6))","choices":["[1] 10","[1] 0","Error: missing value"],"why":"Any NA makes the total unknown. Add <code>na.rm = TRUE</code> to get 10."},
 ]))

# ------------------------------------------------------------------ 2
M.append(dict(id="m2", num=2, lec="Vectors", room="Loot Line", title="The Loot Line",
 tagline="Vectors, coercion, sequences, indexing, recycling, factors and matrices.",
 brief="The loot comes down the line in vectors. One rule governs everything: a vector holds ONE type. Break that rule and R quietly converts your gold into text.",
 objectives=["Build vectors with c(), :, seq() and rep(), including named vectors", "Predict coercion: character > numeric > logical", "Extract with positions, negatives, logicals and names", "Predict recycling and its warning", "Use factors and their levels", "Build, name, slice and multiply matrices"],
 setup=CASE_FILES,
 blocks=[
  {"h":"Loading the line: c()"},
  {"p":"<code>c()</code> combines values into a vector. Never name a variable <code>c</code>. Elements can have names."},
  {"code":"m2_create","src":"loot = c(120, 45, 300)\nitems = c(\"diamonds\", \"watches\", \"gold\")\ncleared = c(TRUE, FALSE, T, F)\nstash = c(diamonds = 120, watches = 45, gold = 300)\nstash"},
  {"h":"The crusher: coercion"},
  {"p":"Mix types in one vector and R converts everything to the most general type: <b>character &gt; numeric &gt; logical</b>. Drop blocks in, then press <b>c()</b> and watch them get crushed into one type."},
  {"lab":"crusher"},
  {"code":"m2_coerce","src":"c(loot, cleared)       # TRUE becomes 1, FALSE becomes 0\nc(items, cleared)\nc(1, \"2\", TRUE)\nc(stash, 99)           # the new element gets an empty name"},
  {"trap":"Once one string sneaks in, the whole vector is text. <code>c(loot, items)[1] + 1</code> fails, because <code>\"120\"</code> isn't a number anymore."},
  {"h":"Sequences: : and seq()"},
  {"code":"m2_seq","src":"1:5\n5:1\n1.5:4.8\nseq(from = 0, to = 1, length.out = 5)\nseq(10, 50, by = 10)\nseq(1, 10, by = pi)      # never passes 'to'\nseq(1, 6, by = 3)\nseq(8)                   # same as 1:8\nseq_len(8)\nseq_along(items)         # 1, 2, 3: one per element"},
  {"h":"Patrol patterns: rep()"},
  {"p":"<code>rep()</code> repeats. <code>times</code> repeats the whole vector, <code>each</code> repeats every element, and <code>length.out</code> stops at an exact length. Build patrol patterns in the lab."},
  {"lab":"rep"},
  {"code":"m2_rep","src":"rep(c(\"L\", \"R\"), times = 3)\nrep(c(\"L\", \"R\"), each = 3)\nrep(c(\"A\", \"B\"), each = 2, times = 2)\nrep(c(\"x\", \"y\", \"z\"), times = c(1, 2, 3))\nrep(1:3, length.out = 8)\nshift = rep(c(\"day\", \"night\"), each = 3)\nshift"},
  {"h":"Vector tools"},
  {"code":"m2_tools","src":"letters[1:6]\nLETTERS[24:26]\nlength(letters)\nnames(stash)\nnames(loot)        # no names: NULL\nis.vector(stash)\nas.vector(stash)   # drops the names"},
  {"h":"The trapdoor: extracting with [ ]"},
  {"p":"Four keys open <code>[ ]</code>: <b>positions</b>, <b>negative positions</b> (drop), <b>logical vectors</b> (keep the TRUEs, recycled if short) and <b>names</b>. Type an index into the lab and watch which loot falls into the bag."},
  {"lab":"lootdrop"},
  {"code":"m2_index","src":"stash[2]\nstash[c(1, 3)]\nstash[\"gold\"]\nstash[-1]\nstash[-c(2, 3)]\nstash[c(TRUE, FALSE, TRUE)]\nstash[stash > 100]\nletters[c(TRUE, FALSE)]   # recycled: every other letter\nstash[5]                  # past the end: NA"},
  {"h":"Swapping the loot: replacement"},
  {"code":"m2_replace","src":"loot = c(120, 45, 300)\nloot[2] = 60\nloot\nloot[5] = 10          # R fills the gap with NA\nloot\nloot[2] = \"sixty\"     # one string turns everything to text\nloot"},
  {"h":"Element-wise and recycling"},
  {"p":"Operations work element by element. When lengths differ, R repeats the shorter vector. If the longer length isn't a multiple of the shorter one, you get a warning, and the result is almost always a bug."},
  {"lab":"recycling"},
  {"code":"m2_recycle","src":"loot = c(120, 45, 300, 80)\nloot * 2\nloot > 100\nsqrt(loot)\nloot + c(10, 20, 30, 40)\nloot + c(1, 1000)\nloot + c(1, 2, 3)"},
  {"h":"Factors: alarm levels"},
  {"p":"A factor is a categorical variable. It stores a fixed set of <b>levels</b> (alphabetical by default) and an integer code per value. A value outside the levels becomes <code>NA</code>. To add values safely, go through character and keep the levels."},
  {"code":"m2_factor","src":"alarm = factor(c(\"silent\", \"loud\", \"silent\", \"none\", \"loud\"))\nalarm\nlevels(alarm)\nas.integer(alarm)\ntable(alarm)\nfactor(c(\"silent\", \"blaring\"), levels = levels(alarm))\nalarm2 = factor(c(as.character(alarm), \"none\"), levels = levels(alarm))\nalarm2\nthreat = factor(c(\"low\", \"high\", \"mid\"), levels = c(\"low\", \"mid\", \"high\"), ordered = TRUE)\nthreat\nthreat < \"high\""},
  {"h":"Safe-deposit boxes: matrices"},
  {"p":"A matrix is a vector with two dimensions, so it still holds one type. <code>matrix()</code> fills <b>down the columns</b> unless you say <code>byrow = TRUE</code>."},
  {"lab":"matrix"},
  {"code":"m2_matrix","src":"boxes = matrix(1:12, nrow = 4, ncol = 3)\nboxes\nboxes = matrix(1:12, nrow = 4, ncol = 3, byrow = TRUE)\nboxes"},
  {"code":"m2_bind","src":"floor1 = c(10, 20, 30)\nfloor2 = c(40, 50, 60)\nrbind(floor1, floor2)\ncbind(floor1, floor2)\nrbind(floor1, c(\"x\", \"y\", \"z\"))   # coercion strikes again"},
  {"code":"m2_matfun","src":"dim(boxes)\nnrow(boxes)\nncol(boxes)\nrownames(boxes) = c(\"North\", \"East\", \"South\", \"West\")\ncolnames(boxes) = c(\"Alpha\", \"Beta\", \"Gamma\")\nboxes\nis.matrix(boxes)\nas.vector(boxes)          # unrolls column by column\nas.matrix(c(\"a\", \"b\"))    # a one-column matrix"},
  {"h":"Opening boxes: [row, column]"},
  {"p":"Leave a side empty to mean “all”. One row or column comes back as a plain vector unless you add <code>drop = FALSE</code>."},
  {"code":"m2_matidx","src":"boxes[1, 2]\nboxes[\"South\", \"Gamma\"]\nboxes[2, ]\nboxes[, 3]\nboxes[, 3, drop = FALSE]\nboxes[c(1, 2), -1]\nboxes[boxes[, \"Alpha\"] > 5, ]"},
  {"h":"Matrix math"},
  {"p":"<code>*</code> multiplies element by element, and a vector recycles <b>down the columns</b>. <code>%*%</code> is true matrix multiplication and needs compatible dimensions: (4×3) times (3×3)."},
  {"code":"m2_matops","src":"boxes + 100\nboxes * boxes\nboxes * 1:3        # recycles DOWN the columns!\nkeys = matrix(1:9, nrow = 3)\nboxes %*% keys"},
 ],
 jobs=[
  {"title":"Odd lock combinations","pay":0.6,"prompt":"Store every odd number from 1 to 19 in <code>ans</code>, using <code>seq()</code>.","starter":"ans = seq(___)","solution":"ans = seq(1, 19, by = 2)","hint":"<code>seq(from, to, by = )</code>."},
  {"title":"Only the big loot","pay":0.8,"prompt":"<code>stash</code> is set for you. Keep only the items worth <b>more than 100</b>, names included, in <code>ans</code>.","setup":"stash = c(diamonds = 120, watches = 45, gold = 300, pearls = 95, art = 410)","starter":"ans = stash[___]","solution":"ans = stash[stash > 100]","hint":"Put a comparison inside the brackets."},
  {"title":"Patrol schedule","pay":0.8,"prompt":"Build the guard patrol <code>A A B B A A B B</code> with <code>rep()</code> and store it in <code>ans</code>.","starter":"ans = rep(___)","solution":"ans = rep(c(\"A\", \"B\"), each = 2, times = 2)","hint":"<code>each</code> first, then <code>times</code>."},
  {"title":"Second column of the vault","pay":1.0,"prompt":"Build a 3×3 matrix filled <b>by row</b> with 1 to 9, then store its <b>second column</b> in <code>ans</code>.","starter":"vault = matrix(___)\nans = vault[___]","solution":"vault = matrix(1:9, nrow = 3, byrow = TRUE)\nans = vault[, 2]","hint":"Filled by row, the second column is 2, 5, 8."},
 ],
 quiz=[
  {"q":"What does this print?","code":"c(1, TRUE, \"a\")","choices":["[1] 1 1 a","[1] \"1\" \"1\" \"a\"","Error: cannot mix types"],"why":"Character wins, so TRUE becomes the text \"TRUE\", not 1."},
  {"q":"What does this print?","code":"rep(c(\"x\", \"y\"), each = 2, times = 2)","choices":["[1] \"x\" \"y\" \"x\" \"y\" \"x\" \"y\" \"x\" \"y\"","[1] \"x\" \"x\" \"y\" \"y\"","[1] \"x\" \"y\" \"x\" \"y\""],"why":"<code>each</code> first (x x y y), then <code>times</code> repeats that block."},
  {"q":"What does this print?","code":"1:6 + c(10, 20)","choices":["[1] 11 22 plus a warning","[1] 11 22","[1] 11 21 12 22 13 23"],"why":"c(10, 20) recycles to 10 20 10 20 10 20. Six is a multiple of two, so no warning."},
  {"q":"What does this print?","code":"x = c(a = 5, b = 7, c = 9)\nx[-2]","choices":["[1] 5 9","b \n7 ","Error: invalid negative subscript"],"why":"A negative index drops that position, and the names come along."},
  {"q":"What does this print?","code":"m = matrix(1:6, nrow = 2)\nm[1, 3]","choices":["[1] 3","[1] 6","Error: subscript out of bounds"],"why":"Filled by column, row 1 is 1 3 5, so position 3 is 5."},
  {"q":"What does this print?","code":"f = factor(c(\"lo\", \"hi\", \"lo\"))\nlevels(f)","choices":["[1] \"lo\" \"hi\"","[1] \"lo\" \"hi\" \"lo\"","[1] 1 2"],"why":"Levels are the unique values, sorted alphabetically."},
 ]))

# ------------------------------------------------------------------ 3
M.append(dict(id="m3", num=3, lec="Matrices & lists", room="Vault Grid", title="The Vault Grid",
 tagline="Transpose, invert, sweep with apply(), stack arrays, pack lists, meet data frames.",
 brief="The vault is a grid. Sweep it row by row and column by column with apply(). Then pack the backpack: a list holds anything, but opening it the wrong way leaves you holding a bag instead of the gold.",
 objectives=["Use t() to work by row and solve() to invert", "Sweep rows and columns with apply(), passing na.rm through", "Index a 3-D array", "Know exactly what [ ], [[ ]] and $ return from a list", "Modify lists; use lapply(), sapply() and unlist()", "See that lm() results and data frames are lists"],
 setup=CASE_FILES,
 blocks=[
  {"h":"Transpose to work by row"},
  {"p":"A vector recycles down columns. To multiply each <b>column</b> by its own number: transpose, multiply, transpose back."},
  {"code":"m3_t","src":"boxes = matrix(1:12, nrow = 4, byrow = TRUE)\nt(boxes)\nboxes * 1:3\nt(t(boxes) * 1:3)"},
  {"h":"Cracking the lock: solve()"},
  {"p":"<code>solve(A)</code> inverts a square matrix. <code>solve(A, b)</code> solves the system A x = b directly, which is how regression is computed under the hood."},
  {"code":"m3_solve","src":"lock = matrix(c(2, 1, 1, 3), nrow = 2)\nlock\nsolve(lock)\nsolve(lock) %*% lock    # identity: the lock is open\nsolve(lock, c(5, 10))   # x such that lock %*% x = (5, 10)"},
  {"h":"The laser sweep: apply()"},
  {"p"
   :"<code>apply(X, MARGIN, FUN)</code> runs one function over every row (<code>MARGIN = 1</code>) or column (<code>MARGIN = 2</code>). Rows come first, just like in <code>[row, col]</code>."},
  {"lab":"apply"},
  {"code":"m3_apply","src":"take = matrix(c(12, 8, 15, 9, 11, 7, 14, 10, 6, 13, 9, 16), nrow = 4, byrow = TRUE,\n              dimnames = list(c(\"Ghost\", \"Viper\", \"Tinker\", \"Nova\"), c(\"Mon\", \"Tue\", \"Wed\")))\ntake\napply(take, MARGIN = 1, FUN = sum)    # per crew member\napply(take, MARGIN = 2, FUN = mean)   # per day\napply(take, 2, max)\nrowSums(take)                         # shortcuts\ncolMeans(take)"},
  {"p":"One <code>NA</code> poisons a sum. Extra arguments after <code>FUN</code> are passed through to the function."},
  {"code":"m3_na","src":"take[2, 3] = NA\napply(take, 1, sum)\napply(take, 1, sum, na.rm = TRUE)"},
  {"h":"Arrays: a building with floors"},
  {"code":"m3_array","src":"building = array(1:24, dim = c(2, 3, 4))   # 2 rows x 3 cols x 4 floors\ndim(building)\nbuilding[, , 1]      # the ground floor\nbuilding[2, 3, 4]    # row 2, col 3, top floor"},
  {"h":"The backpack: lists"},
  {"p":"A list holds anything: vectors, matrices, data frames, even other lists. <code>[ ]</code> gives you <b>a smaller backpack</b>. <code>[[ ]]</code> and <code>$</code> <b>take the item out</b>."},
  {"code":"m3_list","src":"backpack = list(tools = c(\"drill\", \"laptop\", \"rope\"),\n                cash  = c(2500, 1200),\n                map   = matrix(c(\"vault\", \"guard\", \"exit\", \"van\"), nrow = 2))\nbackpack"},
  {"lab":"list"},
  {"code":"m3_bracket","src":"backpack[\"cash\"]\nis.list(backpack[\"cash\"])\nbackpack[[\"cash\"]]\nsum(backpack[[\"cash\"]])\nbackpack$tools[2]\nbackpack$map[1, 2]\nbackpack[c(\"tools\", \"cash\")]\nbackpack[[c(1, 3)]]     # recursive: element 3 inside item 1"},
  {"code":"m3_bracketerr","src":"sum(backpack[\"cash\"])"},
  {"h":"Repacking the bag"},
  {"code":"m3_listmod","src":"backpack$disguise = \"security uniform\"      # add\nbackpack[[\"cash\"]] = c(backpack$cash, 800)  # replace\nbackpack$map = NULL                         # remove\nnames(backpack)\nlapply(backpack, length)    # returns a list\nsapply(backpack, length)    # simplifies to a vector\nunlist(backpack)            # flattens; everything becomes text"},
  {"trap":"<code>backpack[1] = 1:10</code> fails with a warning and keeps only the 1, because <code>[ ]</code> replaces a <i>sub-list</i>. Use <code>[[ ]]</code> or <code>$</code> to replace one item."},
  {"h":"Every model is a list"},
  {"p":"A regression fit is a list, which is why <code>fit$coefficients</code> works."},
  {"code":"m3_lm","src":"fit = lm(mpg ~ hp, data = mtcars)\nis.list(fit)\nnames(fit)[1:5]\nfit$coefficients\nfit$coefficients[\"hp\"] * 100    # mpg lost per extra 100 horsepower"},
  {"h":"Data frames: the crew roster"},
  {"p":"A data frame is a list of equal-length columns that prints like a matrix. Rows are subjects and columns are variables, and each column keeps its own type."},
  {"code":"m3_df","src":"roster = data.frame(codename = c(\"Ghost\", \"Viper\", \"Tinker\"),\n                    age = c(29, 34, 51),\n                    local = c(TRUE, FALSE, TRUE))\nroster\nis.list(roster)\nroster$age\nroster[2, ]"},
 ],
 jobs=[
  {"title":"Daily totals","pay":0.8,"prompt":"<code>take</code> is set for you: crew members in rows, days in columns. Store the <b>total per day</b> in <code>ans</code> using <code>apply()</code>.","setup":"take = matrix(c(12, 8, 15, 9, 11, 7, 14, 10, 6, 13, 9, 16), nrow = 4, byrow = TRUE, dimnames = list(c(\"Ghost\", \"Viper\", \"Tinker\", \"Nova\"), c(\"Mon\", \"Tue\", \"Wed\")))","starter":"ans = apply(take, ___, ___)","solution":"ans = apply(take, 2, sum)","hint":"Days are columns: MARGIN = 2."},
  {"title":"Grab the second stack of cash","pay":0.7,"prompt":"<code>backpack</code> is set for you. Store the <b>second cash amount</b> as a plain number in <code>ans</code>.","setup":"backpack = list(tools = c(\"drill\", \"laptop\"), cash = c(2500, 1200, 800))","starter":"ans = ___","solution":"ans = backpack$cash[2]","hint":"<code>$cash</code> takes the vector out, then use <code>[2]</code>."},
  {"title":"Inventory count","pay":0.8,"prompt":"Store the <b>length of every item</b> in <code>backpack</code> as a named vector in <code>ans</code>.","setup":"backpack = list(tools = c(\"drill\", \"laptop\", \"rope\"), cash = c(2500, 1200), disguise = \"uniform\")","starter":"ans = ___(backpack, ___)","solution":"ans = sapply(backpack, length)","hint":"<code>sapply</code> simplifies to a vector. <code>lapply</code> would give a list."},
 ],
 quiz=[
  {"q":"What does this print?","code":"L = list(a = 1:3, b = \"hi\")\nclass(L[\"a\"])","choices":["[1] \"integer\"","[1] \"character\"","[1] \"numeric\""],"why":"Single brackets always return a list."},
  {"q":"What does this print?","code":"L = list(a = 1:3, b = \"hi\")\nL[[\"a\"]] * 2","choices":["Error: non-numeric argument","$a\n[1] 2 4 6","[1] 1 2 3 1 2 3"],"why":"Double brackets take the vector out."},
  {"q":"What does this print?","code":"m = matrix(1:6, nrow = 2)\napply(m, 2, sum)","choices":["[1]  9 12","[1] 21","[1] 1 2 3 4 5 6"],"why":"MARGIN 2 means columns: (1,2), (3,4), (5,6)."},
  {"q":"What does this print?","code":"length(list(1:10, letters))","choices":["[1] 36","[1] 10","[1] 26"],"why":"A list's length counts its items, not what is inside them."},
  {"q":"What does this print?","code":"dim(array(1:24, dim = c(2, 3, 4)))","choices":["[1] 24","[1] 2 3","[1] 4 3 2"],"why":"<code>dim()</code> gives every dimension in order."},
 ]))

# ------------------------------------------------------------------ 4
M.append(dict(id="m4", num=4, lec="Data frames", room="Intel Files", title="The Intel Files",
 tagline="Inspect, combine and extract from data frames, then pull intel in from files.",
 brief="Intel arrives as tables. Learn to read the files, check every column's type, and add new recruits without corrupting the roster.",
 objectives=["Inspect a data frame with head(), dim(), names(), str()", "Combine with cbind() and rbind() and dodge the vector trap", "Extract rows and columns with [ , ] and $", "Understand stringsAsFactors", "Load built-in data and read .txt, .csv, .xlsx and URLs"],
 setup=CASE_FILES,
 blocks=[
  {"h":"The case file"},
  {"p":"These three tables are loaded in every mission. You can use them in any chunk and in the console."},
  {"code":"m4_casefiles","src":CASE_FILES.replace("set.seed(1337)\n","set.seed(1337)   # makes the random log identical on every computer\n")+"\nhead(vault_log)"},
  {"h":"Inspecting the roster"},
  {"p"
   :"In RStudio, <code>View(crew)</code> opens a spreadsheet view. <code>str()</code> is the fastest way to check every column's type at once."},
  {"code":"m4_inspect","src":"crew\ndim(crew)\nnrow(crew)\nncol(crew)\nnames(crew)          # same as colnames(crew)\nrownames(crew)\nhead(crew, n = 3)\nstr(crew)"},
  {"h":"Recruiting: cbind() and rbind()"},
  {"p":"<code>cbind()</code> needs the same rows in the same order. <code>rbind()</code> matches columns <b>by name</b>, so the column order can differ."},
  {"code":"m4_bind","src":"loyalty = c(9, 6, 10, 4, 7, 8)\ncbind(crew, loyalty)\nrecruits = data.frame(city = c(\"Oslo\", \"Lima\"), codename = c(\"Rook\", \"Lynx\"),\n                      skill = c(\"forger\", \"pilot\"), cut_pct = c(0, 0), age = c(31, 27))\nrbind(crew, recruits)"},
  {"h":"The mole: adding a row with c()"},
  {"p"
   :"A new row written with <code>c()</code> is a vector, and a vector holds one type. Every value becomes text, and rbind drags the whole age column down with it."},
  {"code":"m4_bad","src":"bad = rbind(crew, c(\"Rook\", \"forger\", \"Oslo\", 31, 0))\nstr(bad)\nmean(bad$age)"},
  {"code":"m4_good","src":"good = rbind(crew, data.frame(codename = \"Rook\", skill = \"forger\",\n                              city = \"Oslo\", age = 31, cut_pct = 0))\nmean(good$age)"},
  {"trap":"Always add rows as a one-row <code>data.frame()</code>. When a mean or sum comes back NA or errors out, run <code>str()</code> first."},
  {"h":"Pulling intel: extraction"},
  {"code":"m4_extract","src":"crew[1, \"skill\"]\ncrew$city\ncrew[crew$age < 30, ]\ncrew[crew$city == \"Berlin\", c(\"codename\", \"skill\")]"},
  {"h":"stringsAsFactors"},
  {"p":"Before R 4.0.0, <code>data.frame()</code> turned text into factors by default. Now it doesn't. The good habit is to keep text as character while cleaning, then convert with <code>factor()</code> at the end."},
  {"code":"m4_saf","src":"cities_f = data.frame(city = c(\"Berlin\", \"Tokyo\"), stringsAsFactors = TRUE)\ncities_f$city\nrbind(cities_f, data.frame(city = \"Rio\"))$city   # a new level appears\ncrew$city = factor(crew$city)\nlevels(crew$city)"},
  {"h":"Built-in data"},
  {"code":"m4_builtin","src":"data(mtcars)\nhead(mtcars, 3)\nrownames(mtcars)[1:5]\ndim(iris)\nhead(iris, 3)"},
  {"h":"Reading intel from files"},
  {"p":"<code>read.table()</code> is the general reader: give it the <b>file</b>, whether the first line holds names (<b>header</b>), and the <b>sep</b>arator. <code>read.csv()</code> is read.table with <code>header = TRUE, sep = \",\"</code> preset."},
  {"code":"m4_read","norun":True,"src":"intel = read.table(file = \"intel.txt\", header = TRUE)\nintel = read.table(file = \"intel.csv\", header = TRUE, sep = \",\")\nintel = read.csv(file = \"intel.csv\")                 # same thing, shorter\n\nlibrary(readxl)                                      # Excel\nintel = read_excel(\"intel.xlsx\", sheet = 1)\n# library(xlsx); read.xlsx(\"intel.xlsx\", sheetIndex = 1) also works\n\nintel = read.csv(\"https://example.com/intel.csv\")    # straight from a URL\n\nlibrary(quantmod)                                    # packages can download data too\nAAPL = getSymbols(\"AAPL\", src = \"yahoo\", auto.assign = FALSE)"},
  {"p":"You can see exactly what <code>read.csv()</code> does by giving it text instead of a file:"},
  {"code":"m4_csv","src":"intel = \"target,guards,cash_k,alarm\nGolden Lion,8,950,TRUE\nSilver Palm,4,620,FALSE\nJade Dragon,6,1100,TRUE\"\ncasinos = read.csv(text = intel)\ncasinos\nstr(casinos)\nidentical(casinos, read.table(text = intel, header = TRUE, sep = \",\"))\nread.csv(text = intel, header = FALSE)[1:2, ]    # header = FALSE: names become data"},
  {"h":"Finding the file: paths"},
  {"p":"A relative path is read from the <b>working directory</b>. Check it with <code>getwd()</code> and change it with <code>setwd()</code> or Session › Set Working Directory. On Windows, use <code>/</code> or <code>\\\\</code> in paths, never a single backslash."},
  {"lab":"paths"},
  {"p":"RStudio's <b>Import Dataset</b> button writes the reading code for you. Copy that code into your .Rmd, or the knitted file won't find the data."},
 ],
 jobs=[
  {"title":"The veterans","pay":0.8,"prompt":"Store every crew row (all columns) where <code>age</code> is <b>over 30</b> in <code>ans</code>.","starter":"ans = crew[___, ]","solution":"ans = crew[crew$age > 30, ]","hint":"A logical vector goes in the row slot."},
  {"title":"Recruit Rook properly","pay":1.0,"prompt":"Add Rook (skill <code>\"forger\"</code>, city <code>\"Oslo\"</code>, age 31, cut 0) to <code>crew</code> <b>without</b> breaking the column types. Store the new data frame in <code>ans</code>.","starter":"ans = rbind(crew, ___)","solution":"ans = rbind(crew, data.frame(codename = \"Rook\", skill = \"forger\", city = \"Oslo\", age = 31, cut_pct = 0))","hint":"The new row must be a one-row <code>data.frame()</code>."},
  {"title":"Count the cash","pay":0.8,"prompt":"<code>intel</code> is a CSV string set for you. Read it with <code>read.csv(text = )</code> and store the <b>total</b> of the <code>cash_k</code> column in <code>ans</code>.","setup":"intel = \"target,guards,cash_k,alarm\\nGolden Lion,8,950,TRUE\\nSilver Palm,4,620,FALSE\\nJade Dragon,6,1100,TRUE\"","starter":"casinos = read.csv(text = intel)\nans = ___","solution":"casinos = read.csv(text = intel)\nans = sum(casinos$cash_k)","hint":"<code>sum(casinos$cash_k)</code>"},
 ],
 quiz=[
  {"q":"What does this print?","code":"df = data.frame(x = 1:3, y = c(\"a\", \"b\", \"c\"))\ndf[2, \"y\"]","choices":["[1] 2","  y\n2 b","[1] \"a\" \"b\" \"c\""],"why":"One row and one column give a single value."},
  {"q":"What does this print?","code":"dim(iris)","choices":["[1]   5 150","[1] 150","[1] 750"],"why":"Rows first, then columns."},
  {"q":"What does this print?","code":"df = rbind(data.frame(n = 1:2), c(\"3\"))\nclass(df$n)","choices":["[1] \"integer\"","[1] \"numeric\"","[1] \"factor\""],"why":"The new value is text, so the whole column becomes character."},
  {"q":"<code>read.csv(\"f.csv\")</code> is the same as…","choices":["read.table(\"f.csv\")","read.table(\"f.csv\", sep = \",\")","read.table(\"f.csv\", header = FALSE, sep = \";\")"],"answer":"read.table(\"f.csv\", header = TRUE, sep = \",\")","why":"read.csv presets the header and the comma separator."},
 ]))

# ------------------------------------------------------------------ 5
M.append(dict(id="m5", num=5, lec="Base R wrangling", room="The Sweep", title="The Sweep",
 tagline="Base R data manipulation: which, sample, %in%, duplicated, grep, subset, sort and order.",
 brief="Sixty nights of casino surveillance. Find the richest night, spot the counterfeit serials, crack the password patterns, and line up the crew, all with nothing but base R.",
 objectives=["Turn logicals into positions with which(); know which.max ties and NAs", "Randomize with sample() and set.seed(), including the bootstrap", "Build logical filters with %in%, unique() and duplicated()", "Select by name, and avoid the != recycling trap", "Match patterns with grep(), grepl() and regular expressions", "Filter with subset(); sort with sort() and order()"],
 setup=CASE_FILES,
 blocks=[
  {"p":"“80% of data analysis is spent on the process of cleaning and preparing the data” (Dasu and Johnson, 2003). Every function in this mission builds an <b>index</b> or a <b>logical vector</b> to hand to <code>[ , ]</code>."},
  {"h":"which(): from TRUE to positions"},
  {"code":"m5_which","src":"which(c(FALSE, TRUE, TRUE, FALSE))\nwhich(vault_log$guards == 3)\nvault_log[which(vault_log$guards == 3), ]"},
  {"h":"which.max(): the richest night"},
  {"p":"<code>which.max()</code> and <code>which.min()</code> return only the <b>first</b> position, and they skip NA automatically."},
  {"code":"m5_max","src":"max(vault_log$cash_k)\nwhich.max(vault_log$cash_k)\nvault_log[which.max(vault_log$cash_k), ]\nx = c(5, 2, 2, 9)\nwhich(x == min(x))     # every tie\nwhich.min(x)           # first one only\ny = c(3, NA, 1)\nmin(y)\nmin(y, na.rm = TRUE)\nwhich.min(y)"},
  {"h":"sample(): the lottery machine"},
  {"p":"<code>sample()</code> shuffles or draws. <code>replace = TRUE</code> lets a ball come back, which is the bootstrap. <code>set.seed()</code> makes the draw repeatable, so the same seed always gives the same balls."},
  {"lab":"gumball"},
  {"code":"m5_sample","src":"set.seed(2718)\nsafe_digits = 0:9\nsample(safe_digits)                            # shuffle\nsample(safe_digits, size = 4)                  # no repeats\nsample(safe_digits, size = 4, replace = TRUE)  # repeats allowed\ncrew[sample(1:nrow(crew), size = 2), ]         # a random 2-person team"},
  {"h":"%in%: checking the guest list"},
  {"code":"m5_in","src":"suspects = c(\"Ghost\", \"Rook\", \"Nova\", \"Lynx\", \"Echo\")\nsuspects %in% crew$codename\nsuspects[suspects %in% crew$codename]\nsuspects[!suspects %in% crew$codename]     # strangers\n1:10 %in% c(1, 3, 5, 9)"},
  {"h":"The counterfeit detector: unique() and duplicated()"},
  {"p":"<code>duplicated()</code> marks an element TRUE if it appeared <b>earlier</b>. Add <code>fromLast = TRUE</code> to scan from the end. OR the two together to catch every copy, including the first."},
  {"lab":"duplicated"},
  {"code":"m5_dup","src":"serials = c(\"A17\", \"B22\", \"A17\", \"C09\", \"B22\", \"A17\")\nunique(serials)\nduplicated(serials)\nduplicated(serials, fromLast = TRUE)\nserials[duplicated(serials) | duplicated(serials, fromLast = TRUE)]"},
  {"code":"m5_irisdup","src":"nrow(iris)\nnrow(unique(iris))\niris[duplicated(iris) | duplicated(iris, fromLast = TRUE), ]"},
  {"h":"Selecting by name"},
  {"p":"You can't put a minus sign in front of a name. Drop columns with a logical test instead."},
  {"code":"m5_names","src":"crew[1:3, c(\"codename\", \"skill\")]\ncrew[1:3, colnames(crew) != \"city\"]\ncrew[1:3, !colnames(crew) %in% c(\"city\", \"age\")]"},
  {"code":"m5_nameserr","src":"crew[, -\"city\"]"},
  {"trap":"<code>!=</code> against two names compares <b>position by position</b> with recycling. It only “works” when the names happen to line up. Same question, different order, different answer. Use <code>%in%</code>."},
  {"code":"m5_trap","src":"colnames(crew)\ncolnames(crew) != c(\"city\", \"age\")     # lucky alignment\ncolnames(crew) != c(\"age\", \"city\")     # drops nothing!"},
  {"h":"The code-breaker: grep() and regex"},
  {"p":"<code>grep()</code> returns positions that match a pattern. <code>grepl()</code> returns TRUE/FALSE. <code>^</code> means start, <code>$</code> means end, <code>[A-Z]</code> is a character class, <code>+</code> means one or more, and <code>.</code> means ANY character, so a literal dot is <code>\\\\.</code>."},
  {"lab":"regex"},
  {"code":"m5_grep","src":"grep(\"o\", crew$codename)\ngrepl(\"o\", crew$codename)\ncrew$codename[grepl(\"^[A-M]\", crew$codename)]\npasswords = c(\"vault99\", \"OPEN\", \"1234\", \"gold_bar\", \"gold.bar\", \"x9Y8\")\npasswords[grepl(\"^[A-Za-z0-9]+$\", passwords)]\npasswords[!grepl(\"^[A-Za-z0-9]+$\", passwords)]\ngrepl(\"\\\\.\", passwords)     # literal dot\ngrepl(\".\", passwords)       # any character: all TRUE"},
  {"h":"subset(): readable filters"},
  {"code":"m5_subset","src":"subset(vault_log, subset = guards <= 4 & !alarm, select = c(night, casino, cash_k))\nsubset(crew, subset = age > 30, select = -city)\nsubset(crew, select = skill:age)"},
  {"h":"The lineup: sort() vs order()"},
  {"p":"<code>sort()</code> returns the sorted <b>values</b>. <code>order()</code> returns the <b>positions</b> that would sort them, which is what you need to reorder rows."},
  {"lab":"order"},
  {"code":"m5_sort","src":"ages = crew$age\nages\nsort(ages)\nsort(ages, decreasing = TRUE)\norder(ages)\ncrew[order(crew$age), ]\nres = sort(ages, index.return = TRUE)\nres$ix\ncrew[order(crew$city, -crew$cut_pct), ]   # city A-Z, then biggest cut first"},
 ],
 jobs=[
  {"title":"The Tokyo cell","pay":0.7,"prompt":"Store the <b>codenames</b> of the crew members based in Tokyo in <code>ans</code>.","starter":"ans = crew$codename[___]","solution":"ans = crew$codename[crew$city == \"Tokyo\"]","hint":"A logical test inside the brackets."},
  {"title":"The richest night","pay":0.9,"prompt":"Store the <b>night number</b> (the <code>night</code> column) with the most cash in <code>vault_log</code> in <code>ans</code>.","starter":"ans = vault_log$night[___]","solution":"ans = vault_log$night[which.max(vault_log$cash_k)]","hint":"<code>which.max()</code> gives the row."},
  {"title":"Counterfeit serials","pay":1.0,"prompt":"Store every serial that appears <b>more than once</b>, each listed once, in <code>ans</code>.","setup":"serials = c(\"A17\", \"B22\", \"A17\", \"C09\", \"B22\", \"A17\", \"D40\")","starter":"ans = ___","solution":"ans = unique(serials[duplicated(serials)])","hint":"<code>duplicated()</code> finds the repeats, and <code>unique()</code> removes the extras.","unordered":True},
  {"title":"Pay order","pay":1.0,"prompt":"Store <code>crew</code> sorted by <code>cut_pct</code> from <b>largest to smallest</b> (ties keep their original order) in <code>ans</code>.","starter":"ans = crew[order(___), ]","solution":"ans = crew[order(crew$cut_pct, decreasing = TRUE), ]","hint":"<code>order(..., decreasing = TRUE)</code> or <code>order(-crew$cut_pct)</code>."},
 ],
 quiz=[
  {"q":"What does this print?","code":"which(c(5, 2, 8, 2) == 2)","choices":["[1] 2","[1] FALSE  TRUE FALSE  TRUE","[1] 2 2"],"why":"Every position where the test is TRUE."},
  {"q":"What does this print?","code":"which.min(c(5, 2, 8, 2))","choices":["[1] 2 4","[1] 4","[1] 2 2"],"why":"It stops at the first minimum."},
  {"q":"What does this print?","code":"duplicated(c(\"a\", \"b\", \"a\", \"a\"))","choices":["[1]  TRUE FALSE  TRUE  TRUE","[1] FALSE FALSE  TRUE FALSE","[1] \"a\" \"b\""],"why":"TRUE only if seen before, so the first \"a\" is FALSE."},
  {"q":"What does this print?","code":"order(c(30, 10, 20))","choices":["[1] 10 20 30","[1] 3 1 2","[1] 1 2 3"],"why":"The smallest sits at position 2, then 3, then 1. <code>3 1 2</code> is the rank, a different idea."},
  {"q":"What does this print?","code":"grep(\"a\", c(\"apple\", \"kiwi\", \"banana\"))","choices":["[1]  TRUE FALSE  TRUE","[1] \"apple\"  \"banana\"","[1] 1"],"why":"grep gives positions. grepl would give TRUE/FALSE."},
  {"q":"What does this print?","code":"c(\"cat\", \"dog\", \"bird\") %in% c(\"dog\", \"fish\")","choices":["[1] FALSE  TRUE","[1] \"dog\"","[1] 2"],"why":"One answer per element on the left."},
 ]))

# ------------------------------------------------------------------ 6
M.append(dict(id="m6", num=6, lec="Joining data", room="Getaway Plan", title="The Getaway Plan",
 tagline="Stack tables that line up, merge tables that don't, and never forget the key.",
 brief="The crew list and the job ledger disagree on everything: names, order, even who's real. Tinker pulled two jobs, Blaze and Echo pulled none, and somebody called Rook shows up in the ledger. Merge carefully.",
 objectives=["Use sapply() on data frames", "Know the odd corners of [[ ]] on lists", "Stack with rbind()/cbind() and know when they fail", "Merge with by, by.x/by.y, all, all.x, all.y", "Spot the silent cross join", "Merge on two keys at once"],
 setup=CASE_FILES,
 blocks=[
  {"h":"Review: sapply() on the roster"},
  {"code":"m6_sapply","src":"sapply(crew, is.numeric)\nsapply(crew[, sapply(crew, is.numeric)], mean)\nsapply(crew, class)"},
  {"h":"Review: list corners"},
  {"code":"m6_list","src":"intel = list(x = 1:4, y = letters[1:3])\nintel[[\"x\"]]\nintel[[-1]]          # works only because there are exactly two items\nintel[-1]\nintel[c(TRUE, FALSE)]"},
  {"trap":"<code>[[ ]]</code> is for exactly one item. Negative or logical values inside <code>[[ ]]</code> fail or behave strangely. Use single brackets whenever you mean “a subset”."},
  {"h":"Same order: cbind() and rbind()"},
  {"code":"m6_bind","src":"crew_left = crew[, 1:2]\ncrew_right = crew[, 3:5]\nrebuilt = cbind(crew_left, crew_right)\nidentical(rebuilt, crew)"},
  {"code":"m6_binderr","src":"rbind(crew, crew_left)"},
  {"h":"Different order: merge() on a key"},
  {"p":"The key identifies each person. <code>crew</code> calls it <code>codename</code> and <code>jobs</code> calls it <code>alias</code>, so we pass <code>by.x</code> and <code>by.y</code>."},
  {"code":"m6_show","src":"crew\njobs"},
  {"lab":"joins"},
  {"code":"m6_inner","src":"merge(crew, jobs, by.x = \"codename\", by.y = \"alias\")"},
  {"code":"m6_all","src":"merge(crew, jobs, by.x = \"codename\", by.y = \"alias\", all.x = TRUE)   # keep all crew\nmerge(crew, jobs, by.x = \"codename\", by.y = \"alias\", all.y = TRUE)   # keep all jobs\nnrow(merge(crew, jobs, by.x = \"codename\", by.y = \"alias\", all = TRUE))  # keep everyone"},
  {"p"
   :"If both tables use the same key name, <code>merge()</code> finds it on its own."},
  {"code":"m6_samename","src":"jobs2 = jobs\ncolnames(jobs2)[colnames(jobs2) == \"alias\"] = \"codename\"\nmerge(crew, jobs2)"},
  {"h":"The explosion: forgetting the key"},
  {"p":"With no <code>by</code> and no shared column name, <code>merge()</code> pairs every row with every row. Six crew times six jobs is 36 rows of nonsense, with no warning. Watch it happen:"},
  {"lab":"explosion"},
  {"code":"m6_cross","src":"oops = merge(crew, jobs)\nnrow(oops)\nhead(oops[, c(\"codename\", \"target\")], 4)   # Ghost \"did\" the Casino, the Bank..."},
  {"h":"Two keys at once"},
  {"p":"Guard counts are logged per <b>target</b> per <b>year</b>. A row matches only when both agree."},
  {"code":"m6_twokey","src":"guards = data.frame(target = c(\"Casino\", \"Casino\", \"Bank\", \"Museum\", \"Train\"),\n                    year   = c(2025, 2026, 2025, 2025, 2026),\n                    guards = c(12, 20, 8, 3, 5))\nmerge(jobs, guards, by = c(\"target\", \"year\"))\nmerge(jobs, guards, by = c(\"target\", \"year\"), all.x = TRUE)   # keep Rook's Yacht"},
 ],
 jobs=[
  {"title":"Nobody left behind","pay":0.8,"prompt":"Merge <code>crew</code> and <code>jobs</code>, keeping <b>every crew member</b>, and store the <b>number of rows</b> in <code>ans</code>.","starter":"ans = nrow(merge(___))","solution":"ans = nrow(merge(crew, jobs, by.x = \"codename\", by.y = \"alias\", all.x = TRUE))","hint":"<code>all.x = TRUE</code> keeps the left table."},
  {"title":"The slackers","pay":1.0,"prompt":"Store the codenames of crew members who pulled <b>no jobs</b> in <code>ans</code>.","starter":"ans = crew$codename[___]","solution":"ans = crew$codename[!crew$codename %in% jobs$alias]","hint":"<code>%in%</code> with a <code>!</code> in front.","unordered":True},
  {"title":"Tinker's haul","pay":0.8,"prompt":"Store the <b>total payout</b> for Tinker across all jobs in <code>ans</code>.","starter":"ans = sum(jobs$payout[___])","solution":"ans = sum(jobs$payout[jobs$alias == \"Tinker\"])","hint":"Filter the payout column by alias."},
  {"title":"Measure the damage","pay":0.6,"prompt":"Store the number of rows produced by the accidental <code>merge(crew, jobs)</code> in <code>ans</code>, and think about <i>why</i>.","starter":"ans = ___","solution":"ans = nrow(merge(crew, jobs))","hint":"6 × 6."},
 ],
 quiz=[
  {"q":"How many rows?","code":"nrow(merge(crew, jobs, by.x = \"codename\", by.y = \"alias\"))","choices":["[1] 6","[1] 4","[1] 36"],"why":"Ghost, Viper, Tinker twice and Nova. Blaze, Echo and Rook have no partner."},
  {"q":"How many rows?","code":"nrow(merge(crew, jobs, by.x = \"codename\", by.y = \"alias\", all = TRUE))","choices":["[1] 6","[1] 12","[1] 36"],"why":"The 5 matched rows, plus Blaze, Echo and Rook."},
  {"q":"How many rows?","code":"nrow(merge(crew, jobs))","choices":["[1] 5","[1] 6","Error: no common columns"],"why":"No shared column name means a cross join: 6 × 6."},
  {"q":"What does this print?","code":"sapply(data.frame(a = 1:2, b = c(\"x\", \"y\")), is.numeric)","choices":["[1] TRUE","[1]  TRUE FALSE","    a     b \n TRUE  TRUE "],"why":"sapply keeps the column names."},
 ]))

# ------------------------------------------------------------------ 7
M.append(dict(id="m7", num=7, lec="dplyr & tidyr", room="Pipeline", title="The Pipeline",
 tagline="dplyr and tidyr: the same jobs as Missions 5 and 6, written as a readable plan.",
 brief="A good plan reads like a story: take the log, THEN keep the night shifts, THEN group by casino, THEN summarise. The pipe turns that sentence into code.",
 objectives=["Pipe with %>% and |>, including the . and _ placeholders", "Pick columns with select() and its helpers; pull(), relocate(), rename()", "Pick rows with filter(), the slice family and distinct(); sort with arrange()", "Combine with bind_rows/bind_cols and the six joins", "Create with mutate(), add_row(), case_when()", "Summarise with group_by(), summarise(), across(), count()", "Reshape with pivot_longer() and pivot_wider()"],
 setup=DPLYR+CASE_FILES,
 blocks=[
  {"h":"The pipe"},
  {"p":"<code>%&gt;%</code> (from dplyr) and <code>|&gt;</code> (built into R) pass the left side as the <b>first argument</b> of the right side. The shortcut is <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>M</kbd>. To send it to another argument, use <code>.</code> with <code>%&gt;%</code> or <code>_</code> with <code>|&gt;</code>."},
  {"code":"m7_pipe","src":"library(dplyr)\nnrow(crew)\ncrew |> nrow()\ncrew %>% nrow()\nmtcars |> lm(mpg ~ hp, data = _)\ncrew %>% select(grep(\"c\", colnames(.)))   # . stands for crew"},
  {"h":"Plan the pipeline"},
  {"p":"Build a real dplyr pipeline on <code>vault_log</code>, all 60 nights. Every step shows its R code and its base-R equivalent."},
  {"lab":"dplyr"},
  {"h":"Columns: select() and friends"},
  {"p":"<code>select()</code> takes positions and bare names with <code>:</code>, <code>-</code> and <code>!</code>, but <b>not</b> a logical vector. The helpers are where its power is."},
  {"code":"m7_select","src":"crew %>% select(codename, skill)\ncrew %>% select(-city)\ncrew %>% select(skill:age)\ncrew %>% select(starts_with(\"c\"))\ncrew %>% select(ends_with(\"e\"))\ncrew %>% select(contains(\"_\"))\ncrew %>% select(where(is.numeric))\niris %>% select(matches(\".t.\")) %>% head(2)    # any char + t + any char"},
  {"code":"m7_selecterr","src":"crew %>% select(grepl(\"c\", colnames(.)))"},
  {"code":"m7_cols","src":"crew %>% pull(codename)           # ONE column as a vector\ncrew %>% relocate(city)           # move to the front\ncrew %>% relocate(cut_pct, .after = codename)\ncrew %>% relocate(codename, .after = last_col())\ncrew %>% rename(name = codename, pct = cut_pct)"},
  {"h":"Rows: filter(), slice(), distinct(), arrange()"},
  {"p":"<code>filter()</code> takes <b>conditions</b>. <code>slice()</code> takes <b>positions</b>. Mixing them up is the classic error."},
  {"code":"m7_rows","src":"vault_log %>% filter(casino == \"Jade Dragon\", guards <= 4)   # comma = AND\nvault_log %>% filter(alarm | guards > 10) %>% nrow()\nvault_log %>% slice(1:3)\nvault_log %>% slice_max(cash_k)\nvault_log %>% slice_min(guards, n = 2)\nvault_log %>% slice_tail(prop = 0.05)\nset.seed(1)\nvault_log %>% slice_sample(n = 3)"},
  {"code":"m7_rowerr","src":"vault_log %>% filter(1:5)"},
  {"code":"m7_distinct","src":"vault_log %>% distinct(casino)\nvault_log %>% distinct(casino, shift) %>% nrow()\nvault_log %>% distinct(casino, .keep_all = TRUE)\ncrew %>% arrange(age)\ncrew %>% arrange(desc(cut_pct), age)"},
  {"h":"Combining: bind and join"},
  {"p"
   :"<code>bind_rows()</code> is kinder than <code>rbind()</code>: columns you leave out become NA instead of throwing an error."},
  {"code":"m7_bind","src":"crew %>% bind_rows(data.frame(codename = \"Rook\", skill = \"forger\"))"},
  {"code":"m7_joins","src":"crew %>% inner_join(jobs, by = join_by(codename == alias))\ncrew %>% left_join(jobs, by = join_by(codename == alias)) %>% nrow()\ncrew %>% right_join(jobs, by = join_by(codename == alias)) %>% nrow()\ncrew %>% full_join(jobs, by = join_by(codename == alias)) %>% nrow()\ncrew %>% anti_join(jobs, by = join_by(codename == alias))   # no jobs\ncrew %>% semi_join(jobs, by = join_by(codename == alias)) %>% pull(codename)\njobs %>% anti_join(crew, by = join_by(alias == codename))   # who is Rook?"},
  {"h":"Creating: mutate(), add_row(), case_when()"},
  {"code":"m7_mutate","src":"crew %>% mutate(share = cut_pct / 100, veteran = age >= 35)\ncrew %>% mutate(age_next = age + 1, .after = age, .keep = \"used\")\ncrew %>% add_row(codename = \"Rook\", skill = \"forger\")\nvault_log %>%\n  mutate(level = case_when(guards <= 4 ~ \"soft\",\n                           guards <= 8 ~ \"medium\",\n                           TRUE        ~ \"hard\")) %>%\n  count(level)"},
  {"h":"Summarising: group_by() and summarise()"},
  {"p":"<code>summarise()</code> collapses the table to one row, or one row <b>per group</b> after <code>group_by()</code>. <code>across()</code> applies one function to many columns, like <code>apply()</code>. <code>count()</code> is group_by plus n()."},
  {"code":"m7_summ","src":"vault_log %>% summarise(nights = n(), avg_cash = mean(cash_k), alarms = sum(alarm))\nvault_log %>%\n  group_by(casino) %>%\n  summarise(nights = n(), avg_cash = mean(cash_k), alarm_rate = mean(alarm))\nvault_log %>% group_by(casino, shift) %>% summarise(avg_guards = mean(guards), .groups = \"drop\")\nvault_log %>% count(casino, alarm)\nvault_log %>% group_by(casino) %>% summarise(across(c(guards, cash_k), mean))\niris %>% group_by(Species) %>% summarise(across(contains(\".\"), mean))"},
  {"h":"Reshaping: pivot_longer() and pivot_wider()"},
  {"p":"<b>Wide</b> tables are easy to read. <b>Long</b> tables are easy to compute on and plot. <code>pivot_longer()</code> melts columns into name/value pairs, and <code>pivot_wider()</code> spreads them back."},
  {"lab":"pivot"},
  {"code":"m7_pivot","src":"library(tidyr)\ntakes_wide = data.frame(codename = c(\"Ghost\", \"Viper\", \"Tinker\"),\n                        y2025 = c(0.8, 0.4, 1.5), y2026 = c(0, 0, 0.9))\ntakes_wide\ntakes_long = takes_wide %>% pivot_longer(!codename, names_to = \"year\", values_to = \"take\")\ntakes_long\ntakes_long %>% pivot_wider(names_from = year, values_from = take)\nvault_log %>% count(casino, shift) %>% pivot_wider(names_from = shift, values_from = n)"},
  {"code":"m7_relig","src":"dim(relig_income)\nrelig_income %>%\n  pivot_longer(!religion, names_to = \"income\", values_to = \"count\") %>%\n  head(4)\nfish_encounters %>%\n  pivot_wider(names_from = station, values_from = seen) %>%\n  select(1:6) %>% head(3)"},
 ],
 jobs=[
  {"title":"Quiet night shifts","pay":1.0,"prompt":"From <code>vault_log</code>, keep <b>night</b> shifts with <b>no alarm</b>, and only the columns <code>night</code>, <code>casino</code>, <code>cash_k</code>. Store the result in <code>ans</code>.","starter":"ans = vault_log %>%\n  filter(___) %>%\n  select(___)","solution":"ans = vault_log %>% filter(shift == \"night\", !alarm) %>% select(night, casino, cash_k)","hint":"<code>filter(shift == \"night\", !alarm)</code>"},
  {"title":"Guard report","pay":1.2,"prompt":"Store one row per casino with the <b>mean number of guards</b>, as a two-column table, in <code>ans</code>.","starter":"ans = vault_log %>%\n  group_by(___) %>%\n  summarise(avg_guards = ___)","solution":"ans = vault_log %>% group_by(casino) %>% summarise(avg_guards = mean(guards))","hint":"<code>group_by(casino)</code>, then <code>mean(guards)</code>."},
  {"title":"The slackers, dplyr style","pay":0.8,"prompt":"Using <code>anti_join()</code>, store the crew rows with <b>no jobs</b> in <code>ans</code>.","starter":"ans = crew %>% anti_join(jobs, by = ___)","solution":"ans = crew %>% anti_join(jobs, by = join_by(codename == alias))","hint":"<code>join_by(codename == alias)</code>"},
  {"title":"Melt the takes","pay":1.0,"prompt":"<code>takes_wide</code> is set for you. Turn it <b>long</b>, with columns <code>codename</code>, <code>year</code>, <code>take</code>, and store it in <code>ans</code>.","setup":"takes_wide = data.frame(codename = c(\"Ghost\", \"Viper\", \"Tinker\"), y2025 = c(0.8, 0.4, 1.5), y2026 = c(0, 0, 0.9))","starter":"ans = takes_wide %>% pivot_longer(___)","solution":"ans = takes_wide %>% pivot_longer(!codename, names_to = \"year\", values_to = \"take\")","hint":"<code>!codename</code> means “every column except codename”."},
 ],
 quiz=[
  {"q":"What does this print?","code":"vault_log %>% filter(casino == \"Golden Lion\") %>% nrow()","choices":["[1] 60","[1] 3","[1] 1"],"why":"Each casino has 20 nights."},
  {"q":"What does this print?","code":"crew %>% pull(age) %>% class()","choices":["[1] \"data.frame\"","[1] \"list\"","[1] \"integer\""],"why":"<code>pull</code> hands back the bare column, which is a double vector."},
  {"q":"Which verb picks rows <b>by position</b>?","choices":["filter()","select()","arrange()"],"answer":"slice()","why":"slice uses positions, filter uses conditions, and select works on columns."},
  {"q":"How many rows?","code":"crew %>% left_join(jobs, by = join_by(codename == alias)) %>% nrow()","choices":["[1] 6","[1] 8","[1] 36"],"why":"All six crew are kept, Tinker appears twice, and Rook is dropped."},
  {"q":"What does this print?","code":"data.frame(g = c(\"a\", \"a\", \"b\"), v = c(1, 3, 10)) %>%\n  group_by(g) %>% summarise(m = mean(v)) %>% pull(m)","choices":["[1] 4.666667","[1]  1  3 10","[1] 2"],"why":"One mean per group: a has mean 2, b has mean 10."},
 ]))

# ------------------------------------------------------------------ 8
M.append(dict(id="m8", num=8, lec="Base graphics", room="Surveillance", title="The Surveillance Tapes",
 tagline="Base R graphics: plot() and every argument, layered groups, legends, and plots for distributions.",
 brief="The security footage is data. Plot it right and the pattern jumps out: when the guards thin out, when the cash peaks, which casino trips the most alarms.",
 objectives=["Use plot() on vectors, pairs, functions and models", "Control type, pch, cex, lty, lwd, titles and colors", "Color by group; layer with points(), lines(), legend(), text()", "Fix axis ranges with xlim/ylim", "Save plots to PDF", "Show distributions with hist(), barplot(), boxplot(), and know why pie charts mislead"],
 setup=CASE_FILES,
 blocks=[
  {"h":"Why look at the tapes?"},
  {"p":"A plot shows a whole distribution at once, and relationships jump out. More guards should mean less cash walks out, right? Let's check."},
  {"code":"m8_why","src":"hist(vault_log$cash_k, main = \"Cash in the vault\", xlab = \"Thousands of dollars\", col = \"gold\")","plot":True},
  {"code":"m8_why2","src":"plot(x = mtcars$hp, y = mtcars$mpg)","plot":True},
  {"p":"<code>attach(mtcars)</code> lets you write <code>mpg</code> instead of <code>mtcars$mpg</code>. It's handy for quick exploration but risky in real work, because attached names can hide your own variables. Undo it with <code>detach(mtcars)</code>."},
  {"code":"m8_attach","src":"attach(mtcars)"},
  {"h":"plot() is generic"},
  {"code":"m8_plot1","src":"plot(mpg)                 # one vector: values vs index","plot":True},
  {"code":"m8_sin","src":"plot(sin, from = 0, to = 2 * pi)   # a function","plot":True},
  {"code":"m8_lm","src":"fit = lm(mpg ~ hp)\nsummary(fit)$coefficients\nplot(fit, which = 1)      # a model: residual diagnostics","plot":True},
  {"h":"The control room: every argument"},
  {"p":"Every control below is a real <code>plot()</code> argument, and the R code updates as you go. Paste it into RStudio and you'll get the same picture."},
  {"lab":"plot"},
  {"table":[["Argument","Controls","Try"],["<code>type</code>","points, lines, both","\"p\", \"l\", \"b\""],["<code>pch</code>","point symbol","1 ○, 2 △, 3 +, 16 ●"],["<code>cex</code>","symbol size","1.5 = 50% bigger"],["<code>lty</code>, <code>lwd</code>","line type, width","lty = 2 dashed"],["<code>main</code>, <code>sub</code>","title, subtitle","\"Figure 1\""],["<code>xlab</code>, <code>ylab</code>","axis titles","\"Horsepower\""],["<code>col</code>, <code>col.main</code>, <code>fg</code>","colors","\"orange\", \"#33a02c\""],["<code>xlim</code>, <code>ylim</code>","axis ranges","c(50, 350)"]]},
  {"code":"m8_args","src":"plot(mpg, type = \"b\", pch = 3, cex = 1.5, lty = 2, lwd = 2)","plot":True},
  {"code":"m8_titles","src":"plot(x = hp, y = mpg, main = \"Miles/Gallon v.s. Horsepower\", sub = \"Figure 1\",\n     xlab = \"Horsepower\", ylab = \"Miles/Gallon\",\n     col = \"orange\", col.main = \"skyblue\", fg = \"gray40\")","plot":True},
  {"h":"Color by group"},
  {"p":"<code>col</code> accepts one color per point. Build that vector from a grouping variable. Colors can be names, hex codes like <code>\"#33a02c\"</code>, or picks from the RColorBrewer package."},
  {"code":"m8_colvec","src":"color_vec = rep(\"tmp\", nrow(mtcars))\ncolor_vec[am == 0] = \"#a6cee3\"\ncolor_vec[am == 1] = \"#33a02c\"\nplot(x = hp, y = mpg, col = color_vec, pch = 16,\n     xlab = \"Horsepower\", ylab = \"Miles/Gallon\")","plot":True},
  {"h":"Layers: points(), legend(), text()"},
  {"p":"The first <code>plot()</code> fixes the axis ranges. Points you add later outside that range are silently cut off, so set <code>xlim</code> and <code>ylim</code> first."},
  {"code":"m8_layers","src":"range(hp)\nrange(mpg)\nplot(x = hp[am == 0], y = mpg[am == 0], col = \"#a6cee3\", pch = 1,\n     xlim = c(50, 350), ylim = c(10, 35),\n     main = \"Miles/Gallon v.s. Horsepower\", xlab = \"Horsepower\", ylab = \"Miles/Gallon\")\npoints(x = hp[am == 1], y = mpg[am == 1], col = \"#33a02c\", pch = 2)\nlegend(\"topright\", legend = c(\"Automatic\", \"Manual\"), col = c(\"#a6cee3\", \"#33a02c\"),\n       pch = c(1, 2), title = \"Transmission\", inset = 0.05)\ntext(x = hp, y = mpg, rownames(mtcars), cex = 0.5, pos = 4)","plot":True},
  {"h":"Saving the evidence"},
  {"code":"m8_pdf","norun":True,"src":"pdf(\"surveillance.pdf\", width = 4, height = 4)   # open the file\nplot(sin, from = 0, to = 2 * pi)\ndev.off()                                       # close and save\n# or: Export in the Plots pane"},
  {"h":"Plots for distributions"},
  {"p":"A statistical plot exists to show a <b>distribution</b>. For categories, count with <code>table()</code> and draw bars."},
  {"code":"m8_bar","src":"counts = table(cyl)\ncounts\nbarplot(counts, xlab = \"Number of Cylinders\", ylab = \"Frequency\")","plot":True},
  {"code":"m8_barh","src":"barplot(counts, xlab = \"Frequency\", ylab = \"Number of Cylinders\", horiz = TRUE)","plot":True},
  {"code":"m8_bar2","src":"counts2 = table(cyl, am)\ncounts2\nbarplot(counts2, beside = TRUE, col = c(\"steelblue\", \"tomato\", \"goldenrod\"),\n        names.arg = c(\"Automatic\", \"Manual\"), legend.text = rownames(counts2),\n        args.legend = list(title = \"Number of Cylinders\", x = \"topright\", bty = \"n\"),\n        xlab = \"Transmission\")","plot":True},
  {"code":"m8_heistbar","src":"alarms = table(vault_log$alarm, vault_log$casino)\nalarms\nbarplot(alarms, beside = TRUE, col = c(\"gray70\", \"firebrick\"),\n        legend.text = c(\"quiet\", \"alarm\"), main = \"Alarms by casino\")","plot":True},
  {"code":"m8_box","src":"boxplot(cash_k ~ casino, data = vault_log, col = \"gold\",\n        main = \"Cash per night\", ylab = \"Thousands\")","plot":True},
  {"p":"Pie charts show proportions, but eyes judge lengths far better than angles and areas. Compare this pie with the first bar plot."},
  {"code":"m8_pie","src":"pie(counts)","plot":True},
 ],
 jobs=[
  {"title":"Count the cylinders","pay":0.6,"prompt":"Store the <b>table</b> of <code>mtcars$cyl</code> in <code>ans</code>.","starter":"ans = ___","solution":"ans = table(mtcars$cyl)","hint":"<code>table()</code> counts each category."},
  {"title":"Paint the alarms","pay":0.9,"prompt":"Store a color vector in <code>ans</code>, one per night of <code>vault_log</code>: <code>\"red\"</code> if the alarm went off, else <code>\"grey\"</code>. Then use it in <code>plot(vault_log$night, vault_log$cash_k, col = ans, pch = 16)</code>.","starter":"ans = rep(\"grey\", nrow(vault_log))\nans[___] = \"red\"\nplot(vault_log$night, vault_log$cash_k, col = ans, pch = 16)","solution":"ans = rep(\"grey\", nrow(vault_log))\nans[vault_log$alarm] = \"red\"","hint":"<code>ans[vault_log$alarm] = \"red\"</code> (or <code>ifelse()</code>)."},
  {"title":"Draw the evidence","pay":0.8,"prompt":"Draw any plot of <code>vault_log$guards</code> (a histogram works) and store the <b>number of nights with fewer than 5 guards</b> in <code>ans</code>.","starter":"hist(vault_log$guards)\nans = ___","solution":"ans = sum(vault_log$guards < 5)","hint":"Summing a logical vector counts the TRUEs."},
 ],
 quiz=[
  {"q":"Which argument changes the point symbol?","choices":["cex","lty","type"],"answer":"pch","why":"pch = plotting character. cex scales its size."},
  {"q":"What does this print?","code":"table(mtcars$cyl)","choices":["[1] 4 6 8","[1] 11  7 14","\n 4  6  8 \n32 32 32 "],"why":"A table counts each category: 11, 7 and 14 cars."},
  {"q":"You plot automatics, then add manuals with <code>points()</code>. Some manuals vanish. Why?","choices":["points() only draws 10 points","points() needs type = \"p\"","Manual cars need their own plot() call"],"answer":"The axis ranges were fixed by the first plot()","why":"Set xlim and ylim in the first plot()."},
  {"q":"Why are pie charts discouraged?","choices":["R can't label them","They only work with two categories","They need a legend"],"answer":"Eyes judge lengths well but angles and areas poorly","why":"A bar plot puts the same counts on a common scale."},
 ]))

# ------------------------------------------------------------------ 9 (bonus)
M.append(dict(id="m9", num=9, lec="Programming", room="Playbook", title="The Playbook",
 tagline="Your own functions, if/else, loops, the apply family, and text tools.",
 brief="A mastermind doesn't repeat themselves. Write the plan once as a function, let loops do the grunt work, and format the ransom note with paste() and sprintf().",
 objectives=["Write functions with arguments and defaults", "Branch with if / else if / else, and vectorize with ifelse()", "Loop with for and while, then replace loops with sapply()", "Group with tapply() and aggregate()", "Build text with paste(), paste0(), sprintf(), toupper(), nchar(), substr()"],
 setup=CASE_FILES,
 blocks=[
  {"h":"Functions: write the plan once"},
  {"code":"m9_fun","src":"split_take = function(total, people = 6) {\n  total / people\n}\nsplit_take(600)\nsplit_take(600, people = 4)\nsplit_take(people = 3, total = 900)   # named arguments can go in any order"},
  {"h":"if / else: decisions"},
  {"code":"m9_if","src":"risk = function(guards) {\n  if (guards <= 4) {\n    \"soft target\"\n  } else if (guards <= 8) {\n    \"medium\"\n  } else {\n    \"abort\"\n  }\n}\nrisk(3)\nrisk(11)"},
  {"code":"m9_iferr","src":"risk(c(3, 11))"},
  {"p":"<code>if</code> needs exactly <b>one</b> TRUE or FALSE. For a whole vector, use <code>ifelse()</code> or apply the function to each element with <code>sapply()</code>."},
  {"code":"m9_vec","src":"ifelse(vault_log$guards[1:6] <= 4, \"soft\", \"hard\")\nsapply(c(3, 7, 11), risk)"},
  {"h":"Loops"},
  {"code":"m9_for","src":"for (name in crew$codename) {\n  cat(name, \"is in position\\n\")\n}\ntotal = 0\nfor (p in jobs$payout) total = total + p\ntotal\nsum(jobs$payout)     # R's vectorized way: same answer, one line"},
  {"code":"m9_while","src":"set.seed(7)\ntries = 0\ndigit = -1\nwhile (digit != 7) {           # keep guessing until we hit 7\n  digit = sample(0:9, 1)\n  tries = tries + 1\n}\ntries"},
  {"h":"The apply family"},
  {"table":[["Function","Input","Output"],["<code>apply(X, MARGIN, f)</code>","matrix rows/columns","vector or matrix"],["<code>lapply(X, f)</code>","each element of a list/vector","list"],["<code>sapply(X, f)</code>","each element","simplified vector"],["<code>tapply(x, group, f)</code>","x split by a group","one value per group"],["<code>aggregate(y ~ g, data, f)</code>","formula by group","data frame"]]},
  {"code":"m9_apply","src":"sapply(crew$age, function(a) a + 1)\nsapply(crew$age, \\(a) a + 1)         # \\(a) is shorthand for function(a)\ntapply(vault_log$cash_k, vault_log$casino, mean)\naggregate(cash_k ~ casino, data = vault_log, FUN = mean)\naggregate(cash_k ~ casino + shift, data = vault_log, FUN = max)"},
  {"h":"Text tools: the ransom note"},
  {"code":"m9_text","src":"paste(\"Agent\", crew$codename)\npaste0(crew$codename, \"@\", crew$city)\npaste(crew$codename, collapse = \" + \")\nsprintf(\"%s takes %d%%\", crew$codename, crew$cut_pct)\nsprintf(\"$%.2f million\", 1234.5678 / 1000)\ntoupper(\"ghost\")\nnchar(crew$codename)\nsubstr(\"Nightingale\", 1, 5)"},
 ],
 jobs=[
  {"title":"Write cut_of()","pay":1.2,"prompt":"Write a function <code>cut_of(total, pct)</code> that returns <code>total * pct / 100</code>. It must work on vectors too.","starter":"cut_of = function(total, pct) {\n  ___\n}\ncut_of(1000, 20)","check":"is.function(cut_of) && isTRUE(all.equal(cut_of(1000, 20), 200)) && isTRUE(all.equal(cut_of(500, c(10, 50)), c(50, 250)))","solution":"cut_of = function(total, pct) {\n  total * pct / 100\n}","hint":"The body is one line: <code>total * pct / 100</code>."},
  {"title":"Alarms per casino","pay":1.0,"prompt":"Store the <b>number of alarm nights per casino</b> (a named vector) in <code>ans</code>, using <code>tapply()</code>.","starter":"ans = tapply(___, ___, ___)","solution":"ans = tapply(vault_log$alarm, vault_log$casino, sum)","hint":"Summing a logical counts the TRUEs."},
  {"title":"Name tags","pay":0.8,"prompt":"Store tags like <code>\"GHOST (Berlin)\"</code> for every crew member in <code>ans</code>, using <code>toupper()</code> and <code>paste0()</code>.","starter":"ans = paste0(___)","solution":"ans = paste0(toupper(crew$codename), \" (\", crew$city, \")\")","hint":"<code>paste0(toupper(crew$codename), \" (\", crew$city, \")\")</code>"},
 ],
 quiz=[
  {"q":"What does this print?","code":"f = function(x, y = 2) x ^ y\nf(3)","choices":["[1] 6","[1] 3","Error: argument \"y\" is missing"],"why":"y defaults to 2, so 3² = 9."},
  {"q":"What does this print?","code":"ifelse(c(1, 5, 9) > 4, \"hi\", \"lo\")","choices":["[1] \"hi\"","Error: the condition has length > 1","[1] \"lo\" \"lo\" \"hi\""],"why":"ifelse works element by element."},
  {"q":"What does this print?","code":"paste(\"a\", \"b\", sep = \"-\")","choices":["[1] \"a b\"","[1] \"ab\"","[1] \"a\" \"b\""],"why":"sep goes between the pieces."},
 ]))

# ------------------------------------------------------------------ 10 (bonus)
M.append(dict(id="m10", num=10, lec="Simulation", room="The Odds", title="The Odds",
 tagline="Simulation, probability, the bootstrap, and the Central Limit Theorem, with real physics.",
 brief="Before the crew commits, the mastermind runs the job ten thousand times in simulation. Probability is just a long-run average, and R can run the long run in a second.",
 objectives=["Simulate with sample(), runif(), rbinom(), rnorm() and replicate()", "Estimate a probability as the mean of a logical vector", "Compare simulation to the exact answer (and to pnorm())", "Read quantiles; bootstrap a confidence interval", "Watch the Central Limit Theorem build a bell curve from chaos"],
 setup=CASE_FILES,
 blocks=[
  {"h":"Probability is a long-run average"},
  {"p"
   :"The mean of a TRUE/FALSE vector is the <b>proportion of TRUEs</b>. Simulate something many times and that proportion estimates its probability."},
  {"code":"m10_dice","src":"set.seed(1337)\nrolls = sample(1:6, 10, replace = TRUE)\nrolls\nrolls == 6\nmean(rolls == 6)                         # 10 rolls: noisy\nmean(sample(1:6, 1e5, replace = TRUE) == 6)   # 100,000 rolls: close to 1/6\n1 / 6"},
  {"h":"Simulating the heist"},
  {"p"
   :"The job has three independent obstacles. You slip past the camera 90% of the time, the guard 80%, and crack the vault 70%. Run the heist thousands of times in the simulator, then in R."},
  {"lab":"heistsim"},
  {"code":"m10_heist","src":"set.seed(1)\none_try = function() {\n  runif(1) < 0.9 & runif(1) < 0.8 & runif(1) < 0.7\n}\none_try()\nresults = replicate(10000, one_try())\nmean(results)        # simulated success rate\n0.9 * 0.8 * 0.7      # exact answer for independent steps"},
  {"h":"Distributions"},
  {"code":"m10_norm","src":"set.seed(3)\ncash = rnorm(1000, mean = 800, sd = 150)\nmean(cash)\nsd(cash)\nquantile(cash, c(0.05, 0.5, 0.95))\nmean(cash > 1000)                  # simulated P(cash > 1000)\n1 - pnorm(1000, mean = 800, sd = 150)   # exact\nhist(cash, breaks = 30, col = \"gold\", main = \"Simulated vault cash\")\nabline(v = 1000, col = \"red\", lwd = 3)","plot":True},
  {"code":"m10_binom","src":"set.seed(2)\nrbinom(10, size = 1, prob = 0.3)        # ten nights: alarm (1) or not (0)\nrbinom(5, size = 20, prob = 0.3)        # alarms in five 20-night months\ndbinom(0:3, size = 20, prob = 0.3)      # exact P(0), P(1), P(2), P(3)"},
  {"h":"The Galton board: the CLT with real physics"},
  {"p":"Each ball bounces left or right at every peg, so its final bin is a <b>sum of many small random pushes</b>. Sums of many independent pushes pile up into a bell curve. That's the Central Limit Theorem from Mission 1, happening in front of you."},
  {"lab":"galton"},
  {"h":"The CLT in R"},
  {"p"
   :"Draw from a badly skewed distribution. Take the <b>mean</b> of 30 draws. Do that 5000 times. The means form a bell curve centred on the true mean with spread σ/√n, just like the formula said."},
  {"lab":"clt"},
  {"code":"m10_clt","src":"set.seed(4)\nmeans = replicate(5000, mean(rexp(30, rate = 1)))\nmean(means)          # true mean is 1\nsd(means)\n1 / sqrt(30)         # sigma / sqrt(n)\nhist(means, breaks = 40, col = \"skyblue\", main = \"5000 means of 30 skewed draws\")","plot":True},
  {"h":"The bootstrap"},
  {"p"
   :"We only have 60 nights of data. Resample those nights <b>with replacement</b> thousands of times, and the spread of the resampled means shows how uncertain our average is."},
  {"code":"m10_boot","src":"set.seed(5)\nboot_means = replicate(2000, mean(sample(vault_log$cash_k, replace = TRUE)))\nmean(vault_log$cash_k)\nquantile(boot_means, c(0.025, 0.975))   # 95% bootstrap interval"},
 ],
 jobs=[
  {"title":"At least one six","pay":1.2,"prompt":"Estimate by simulation the probability of rolling <b>at least one 6 in 4 rolls</b>. Store it in <code>ans</code>. It must land within 0.02 of the exact answer.","starter":"sims = replicate(10000, any(sample(1:6, 4, replace = TRUE) == ___))\nans = mean(sims)","check":"is.numeric(ans) && length(ans) == 1 && abs(ans - (1 - (5/6)^4)) < 0.02","solution":"sims = replicate(10000, any(sample(1:6, 4, replace = TRUE) == 6))\nans = mean(sims)","hint":"<code>any(... == 6)</code> is TRUE when at least one roll is a 6."},
  {"title":"Lucky seven","pay":1.0,"prompt":"Simulate 10,000 rolls of <b>two dice</b> and store the proportion of sums equal to 7 in <code>ans</code> (within 0.015 of 1/6).","starter":"d1 = sample(1:6, 10000, replace = TRUE)\nd2 = ___\nans = mean(___)","check":"is.numeric(ans) && length(ans) == 1 && abs(ans - 1/6) < 0.015","solution":"d1 = sample(1:6, 10000, replace = TRUE)\nd2 = sample(1:6, 10000, replace = TRUE)\nans = mean(d1 + d2 == 7)","hint":"<code>mean(d1 + d2 == 7)</code>"},
  {"title":"Exact odds","pay":0.6,"prompt":"Store the <b>exact</b> probability that all three obstacles are cleared (0.9, 0.8, 0.7, independent) in <code>ans</code>.","starter":"ans = ___","solution":"ans = 0.9 * 0.8 * 0.7","hint":"Independent events multiply."},
 ],
 quiz=[
  {"q":"What does this print?","code":"mean(c(TRUE, FALSE, TRUE, TRUE))","choices":["[1] 3","[1] TRUE","Error: argument is not numeric"],"why":"TRUE counts as 1, so 3 of 4 gives 0.75."},
  {"q":"Why does <code>set.seed()</code> matter?","choices":["It makes random numbers more random","It speeds up sample()","It's required before rnorm()"],"answer":"It makes the same random draws happen every time","why":"Same seed, same draws. That makes work reproducible."},
  {"q":"Means of samples of size n spread out by about…","choices":["σ","σ × n","σ / n"],"answer":"σ / √n","why":"That's the √n in the CLT formula. Quadruple n and the spread halves."},
 ]))

