CAPSTONE = dict(id="final", title="The Big Score",
 brief="Everything at once. Four jobs, each needing tools from several missions. Solve them all and the vault is yours.",
 setup=DPLYR+CASE_FILES,
 jobs=[
  {"title":"Who got paid?","pay":2.5,"prompt":"Each person's take is <code>payout × cut_pct / 100</code>, summed over their jobs. Build a data frame with columns <code>codename</code> and <code>take</code> for <b>every</b> crew member (Blaze and Echo get 0), sorted <b>richest first</b>. Store it in <code>ans</code>.","starter":"ans = crew %>%\n  left_join(jobs, by = join_by(codename == alias)) %>%\n  ___","solution":"ans = crew %>% left_join(jobs, by = join_by(codename == alias)) %>% mutate(take = coalesce(payout * cut_pct / 100, 0)) %>% group_by(codename) %>% summarise(take = sum(take)) %>% arrange(desc(take))","hint":"mutate the take, turn NA into 0 with <code>coalesce(x, 0)</code> or <code>ifelse(is.na(x), 0, x)</code>, then group_by + summarise + arrange(desc())."},
  {"title":"The loudest casino","pay":1.5,"prompt":"Store the <b>name</b> of the casino with the highest alarm rate (proportion of nights with an alarm) in <code>ans</code>, as a single string.","starter":"ans = vault_log %>%\n  ___","solution":"ans = vault_log %>% group_by(casino) %>% summarise(rate = mean(alarm)) %>% slice_max(rate) %>% pull(casino)","hint":"group_by, <code>summarise(rate = mean(alarm))</code>, <code>slice_max(rate)</code>, <code>pull(casino)</code>."},
  {"title":"The shift grid","pay":2.0,"prompt":"Build a table with one row per casino and one column per shift (<code>day</code>, <code>night</code>) holding the <b>mean cash</b>. Store it in <code>ans</code> with columns <code>casino</code>, <code>day</code>, <code>night</code>.","starter":"ans = vault_log %>%\n  group_by(casino, shift) %>%\n  summarise(avg = mean(cash_k), .groups = \"drop\") %>%\n  ___","solution":"ans = vault_log %>% group_by(casino, shift) %>% summarise(avg = mean(cash_k), .groups = \"drop\") %>% pivot_wider(names_from = shift, values_from = avg)","hint":"<code>pivot_wider(names_from = shift, values_from = avg)</code>"},
  {"title":"Plan B","pay":2.0,"prompt":"Write <code>best_night(df)</code>: given a log like <code>vault_log</code>, it returns the <code>night</code> number with the most cash among nights <b>with no alarm and 5 or fewer guards</b>.","starter":"best_night = function(df) {\n  ___\n}\nbest_night(vault_log)","check":"is.function(best_night) && { d <- vault_log[!vault_log$alarm & vault_log$guards <= 5, ]; identical(as.numeric(best_night(vault_log)), as.numeric(d$night[which.max(d$cash_k)])) } && { v2 <- vault_log; v2$cash_k <- rev(v2$cash_k); d2 <- v2[!v2$alarm & v2$guards <= 5, ]; identical(as.numeric(best_night(v2)), as.numeric(d2$night[which.max(d2$cash_k)])) }","solution":"best_night = function(df) {\n  d = df[!df$alarm & df$guards <= 5, ]\n  d$night[which.max(d$cash_k)]\n}","hint":"Filter the rows inside the function, then use <code>which.max()</code>. It's tested on a second, shuffled log too."},
 ])
